using System.Net;
using System.Net.Http.Json;
using System.Text.Json;
using BuildingFlow.Application;
using BuildingFlow.Domain;
using BuildingFlow.Infrastructure;
using Microsoft.AspNetCore.Hosting;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.DependencyInjection.Extensions;
using Microsoft.Extensions.Configuration;
using Microsoft.EntityFrameworkCore;
using Xunit;
namespace BuildingFlow.IntegrationTests;
public sealed class WebsiteDomainApiTests(SiteApiTests.SiteApiFactory factory):IClassFixture<SiteApiTests.SiteApiFactory>{
 private static string Root(Guid p)=>$"/api/v1/properties/{p}/website";
 private async Task<(Property P,string Actor,HttpClient C,WebsiteResponse Site)> Seed(){var p=new Property("Domain fixture","City","District","Address");var actor=Guid.NewGuid().ToString();await factory.WithDb(async db=>{db.AddRange(p,new PropertyMembership(p.Id,actor));await db.SaveChangesAsync();});var c=TestToken.Client(factory,actor,"SITE_ADMIN");var response=await c.PostAsJsonAsync(Root(p.Id),new WebsiteCreateRequest(Guid.NewGuid(),"domain-"+actor[..8],"Fixture"));Assert.Equal(HttpStatusCode.Created,response.StatusCode);return(p,actor,c,(await response.Content.ReadFromJsonAsync<WebsiteResponse>())!);}
 [PostgresFact]public async Task DnsTlsApprovalScopeVersionAndImmediateRevocation(){var x=await Seed();using var auth=x.C;var verifier=new Verifier();using var child=factory.WithWebHostBuilder(b=>b.ConfigureServices(s=>{s.RemoveAll<IWebsiteDomainVerifier>();s.AddSingleton<IWebsiteDomainVerifier>(verifier);}));using var c=child.CreateClient();c.DefaultRequestHeaders.Authorization=auth.DefaultRequestHeaders.Authorization;var path=Root(x.P.Id)+"/domains";var host="fixture-"+Guid.NewGuid().ToString("N")+".example.com";var request=new WebsiteDomainCreate(Guid.NewGuid(),host,"CUSTOM");var created=await c.PostAsJsonAsync(path,request);Assert.Equal(HttpStatusCode.OK,created.StatusCode);var d=(await created.Content.ReadFromJsonAsync<WebsiteDomainDto>())!;Assert.NotNull(d.VerificationToken);verifier.Hash=WebsiteImage.Sha(System.Text.Encoding.UTF8.GetBytes(d.VerificationToken!));Assert.Null((await (await c.PostAsJsonAsync(path,request)).Content.ReadFromJsonAsync<WebsiteDomainDto>())!.VerificationToken);Assert.DoesNotContain(d.VerificationToken!,await c.GetStringAsync(path));using var accountant=TestToken.Client(factory,x.Actor,"ACCOUNTANT");Assert.Equal(HttpStatusCode.Forbidden,(await accountant.GetAsync(path)).StatusCode);using var outsider=TestToken.Client(factory,Guid.NewGuid().ToString(),"SITE_ADMIN");Assert.Equal(HttpStatusCode.NotFound,(await outsider.GetAsync(path)).StatusCode);Assert.Equal(HttpStatusCode.Forbidden,(await c.PostAsJsonAsync(path+$"/{d.Id}/approve",new WebsiteDomainAction(d.Version))).StatusCode);
 async Task<WebsiteDomainDto> Act(string name,HttpClient? client=null){var r=await (client??c).PostAsJsonAsync(path+$"/{d.Id}/{name}",new WebsiteDomainAction(d.Version));Assert.Equal(HttpStatusCode.OK,r.StatusCode);return(await r.Content.ReadFromJsonAsync<WebsiteDomainDto>())!;}
 d=await Act("verify");Assert.Equal("PENDING",d.Status);using var superToken=TestToken.Client(factory,"fixture-super","SUPER_ADMIN");using var super=child.CreateClient();super.DefaultRequestHeaders.Authorization=superToken.DefaultRequestHeaders.Authorization;d=await Act("approve",super);d=await Act("verify");Assert.Equal("PENDING",d.Status);verifier.Dns=true;d=await Act("verify");Assert.Equal("PENDING",d.Status);verifier.Tls=true;var previous=d.Version;d=await Act("verify");Assert.Equal("VERIFIED",d.Status);Assert.Equal(HttpStatusCode.Conflict,(await c.PostAsJsonAsync(path+$"/{d.Id}/primary",new WebsiteDomainAction(previous))).StatusCode);d=await Act("primary");using var anon=factory.CreateClient();var pub="/api/public/v1/domains/"+host;Assert.Equal(HttpStatusCode.NotFound,(await anon.GetAsync(pub)).StatusCode);await factory.WithDb(async db=>{var s=await db.Set<WebsiteSite>().SingleAsync(s=>s.Id==x.Site.Id);s.MarkPublished();db.Add(new WebsitePublication(x.P.Id,s.Id,Guid.NewGuid(),1,"{}",new string('a',64),DateTimeOffset.UtcNow,null,null));await db.SaveChangesAsync();});Assert.Equal(HttpStatusCode.OK,(await anon.GetAsync(pub)).StatusCode);Assert.DoesNotContain("propertyId",await anon.GetStringAsync(pub));d=await Act("disable");Assert.Equal(HttpStatusCode.NotFound,(await anon.GetAsync(pub)).StatusCode);d=await Act("verify");Assert.Equal(HttpStatusCode.OK,(await anon.GetAsync(pub)).StatusCode);var rotated=await Act("rotate");Assert.NotNull(rotated.VerificationToken);Assert.Equal(HttpStatusCode.NotFound,(await anon.GetAsync(pub)).StatusCode);d=rotated;Assert.Equal(HttpStatusCode.OK,(await c.DeleteAsync(path+$"/{d.Id}?version={d.Version}")).StatusCode);Assert.Equal(HttpStatusCode.Conflict,(await c.PostAsJsonAsync(path,request)).StatusCode);}
 [PostgresFact]public async Task SignedPreviewCannotExposeOtherSiteOrSurviveDraftChanges(){var x=await Seed();using var auth=x.C;var config=new ConfigurationBuilder().AddInMemoryCollection(new Dictionary<string,string?>{{"Website:PreviewHmacKey",Convert.ToBase64String(new byte[32])}}).Build();using var child=factory.WithWebHostBuilder(b=>b.ConfigureServices(s=>{s.RemoveAll<WebsitePreviewProtection>();s.AddSingleton(new WebsitePreviewProtection(config,TimeProvider.System));}));using var c=child.CreateClient();c.DefaultRequestHeaders.Authorization=auth.DefaultRequestHeaders.Authorization;var response=await c.PostAsJsonAsync(Root(x.P.Id)+"/preview-token",new WebsiteVersionRequest(x.Site.Version));Assert.Equal(HttpStatusCode.OK,response.StatusCode);var token=(await response.Content.ReadFromJsonAsync<WebsitePreviewIssue>())!.Token;using var anon=child.CreateClient();var read=await anon.PostAsJsonAsync("/api/public/v1/preview",new WebsitePreviewRequest(token));Assert.Equal(HttpStatusCode.OK,read.StatusCode);var raw=await read.Content.ReadAsStringAsync();Assert.Contains(x.Site.SiteKey,raw);Assert.DoesNotContain("propertyId",raw);Assert.Contains("noindex",read.Headers.GetValues("X-Robots-Tag").Single());Assert.Equal(HttpStatusCode.NotFound,(await anon.PostAsJsonAsync("/api/public/v1/preview",new WebsitePreviewRequest(token+"x"))).StatusCode);Assert.Equal(HttpStatusCode.NotFound,(await anon.PostAsJsonAsync("/api/public/v1/preview/media/"+Guid.NewGuid()+"/"+new string('a',64),new WebsitePreviewRequest(token))).StatusCode);await factory.WithDb(async db=>{var s=await db.Set<WebsiteSite>().SingleAsync(s=>s.Id==x.Site.Id);s.UpdateDetails("Changed",null,null,null,true);await db.SaveChangesAsync();});Assert.Equal(HttpStatusCode.NotFound,(await anon.PostAsJsonAsync("/api/public/v1/preview",new WebsitePreviewRequest(token))).StatusCode);}
 [PostgresFact]public async Task WorkerRecheckRenewsOnlyDueVerifiedDomainsAndFailedProbesChangeNothing(){var x=await Seed();x.C.Dispose();var stale=DateTimeOffset.UtcNow.AddHours(-7);WebsiteDomain Row(string host,bool verified,DateTimeOffset at){var d=new WebsiteDomain(x.P.Id,x.Site.Id,Guid.NewGuid(),host,"CUSTOM",new string('a',64));d.Approve(at);if(verified)d.Check(true,true,at);return d;}
 var tag=Guid.NewGuid().ToString("N");var due=Row("due-"+tag+".example.com",true,stale);var fresh=Row("fresh-"+tag+".example.com",true,DateTimeOffset.UtcNow.AddHours(-1));var pending=Row("pending-"+tag+".example.com",false,stale);await factory.WithDb(async db=>{db.AddRange(due,fresh,pending);await db.SaveChangesAsync();});
 var verifier=new Verifier{Dns=true,Tls=true,Hash=new string('a',64)};using var child=factory.WithWebHostBuilder(b=>b.ConfigureServices(s=>{s.RemoveAll<IWebsiteDomainVerifier>();s.AddSingleton<IWebsiteDomainVerifier>(verifier);}));
 async Task<int> Recheck(){await using var scope=child.Services.CreateAsyncScope();return await scope.ServiceProvider.GetRequiredService<IWebsiteDomainStore>().Recheck(1000,CancellationToken.None);}
 async Task<WebsiteDomain> Load(Guid id){WebsiteDomain? d=null;await factory.WithDb(async db=>d=await db.Set<WebsiteDomain>().AsNoTracking().SingleAsync(r=>r.Id==id));return d!;}
 verifier.Tls=false;await Recheck();var unchanged=await Load(due.Id);Assert.Equal("VERIFIED",unchanged.Status);Assert.Equal(due.LastCheckedAt!.Value.ToUnixTimeSeconds(),unchanged.LastCheckedAt!.Value.ToUnixTimeSeconds());Assert.Equal(due.Version,unchanged.Version);
 verifier.Tls=true;Assert.True(await Recheck()>=1);var renewed=await Load(due.Id);Assert.Equal("VERIFIED",renewed.Status);Assert.True(renewed.LastCheckedAt>DateTimeOffset.UtcNow.AddMinutes(-5));Assert.True(renewed.TlsCheckedAt>DateTimeOffset.UtcNow.AddMinutes(-5));Assert.True(renewed.Version>due.Version);
 Assert.Equal(fresh.LastCheckedAt!.Value.ToUnixTimeSeconds(),(await Load(fresh.Id)).LastCheckedAt!.Value.ToUnixTimeSeconds());var stillPending=await Load(pending.Id);Assert.Equal("PENDING",stillPending.Status);Assert.Null(stillPending.LastCheckedAt);}
 private sealed class Verifier:IWebsiteDomainVerifier{public bool Dns;public bool Tls;public string? Hash;public Task<(bool Dns,bool Tls)> Check(string host,string hash,CancellationToken t)=>Task.FromResult((Dns&&Hash==hash,Tls));}
}
